// ============================================
// RÉCUPÉRATION DU SOURCE_ID DU WEBHOOK
// ============================================

// Méthode 1: Depuis le node "Webhook" directement par son nom
let webhookData = {};
try {
  // Cherche le node appelé "Webhook" (ou le nom exact de votre node)
  webhookData = $items("Webhook")[0]?.json || {};
} catch (e) {
  webhookData = {};
}

// Si pas trouvé, essaie avec l'ID du node
if (!webhookData.body?.source_id) {
  try {
    // Ou utilise le premier node du workflow
    const allNodes = Object.keys($execution.runData || {});
    const firstNode = allNodes[0];
    webhookData = $items(firstNode)[0]?.json || {};
  } catch (e2) {
    // ignore
  }
}

const sourceId = webhookData.body?.source_id || webhookData.source_id || null;

// ============================================
// PARSAGE RÉPONSE LLM (node actuel)
// ============================================

const llmOutput = $json.text || "";

const cleanJson = llmOutput
  .replace(/\\n/g, '')
  .replace(/\\"/g, '"')
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = { keywords: [] };
}

// ============================================
// RETOUR FINAL
// ============================================

return {
  json: {
    keywords: parsed.keywords || [],
    source_id: sourceId,
    nb_mots_cles: (parsed.keywords || []).length,
    methode: "agent_ai_llm_studia",
    timestamp: new Date().toISOString(),
    debug_webhook_found: !!webhookData.body  // Pour debug
  }
};
